// pages/UserProfile.tsx
import React, { useState, useEffect } from 'react';
import { useAuth } from '../contexts/AuthContext';
import { apiService } from '../services/api';
import './UserProfile.css';

const UserProfile: React.FC = () => {
  const { user, logout } = useAuth();
  const [minioInfo, setMinioInfo] = useState<any>(null);
  const [loading, setLoading] = useState(true);
  const [userFiles, setUserFiles] = useState<any[]>([]);
  const [activeTab, setActiveTab] = useState<'account' | 'files'>('account');
  const [debugInfo, setDebugInfo] = useState<string>('');
  const [refreshing, setRefreshing] = useState(false);

  useEffect(() => {
    const loadUserData = async () => {
      if (user) {
        try {
          console.log('🔄 [Profile] Loading user data...');
          setDebugInfo('Начинаю загрузку данных...\n');

          // Загружаем информацию о MinIO
          try {
            const info = await apiService.getUserMinioInfo();
            console.log('📦 [Profile] MinIO Info:', info);
            setMinioInfo(info);
            setDebugInfo(prev => prev + '✅ MinIO информация загружена\n');
          } catch (minioError: any) {
            console.warn('⚠️ [Profile] Could not load MinIO info:', minioError);
            setDebugInfo(prev => prev + `⚠️ Не удалось загрузить MinIO информацию: ${minioError.message}\n`);
            setMinioInfo({
              username: user.username,
              files_bucket: 'user-files',
              user_folder: user.username,
              storage_used: '0 B',
              provider: 'MinIO',
              error: minioError.message
            });
          }

          // Загружаем файлы из MinIO
          await loadFilesFromMinIO();

        } catch (error: any) {
          console.error('❌ [Profile] Error loading user data:', error);
          setDebugInfo(prev => prev + `❌ Ошибка загрузки: ${error.message || JSON.stringify(error)}\n`);

          // Покажем тестовые данные для отладки
          setUserFiles([
            {
              name: 'test-image-1.jpg',
              url: 'https://via.placeholder.com/300x200/667eea/ffffff?text=Test+1',
              size: 102400,
              last_modified: new Date().toISOString(),
              type: 'image/jpeg',
              object_name: `${user.username}/test-image-1.jpg`
            },
            {
              name: 'test-image-2.png',
              url: 'https://via.placeholder.com/300x200/764ba2/ffffff?text=Test+2',
              size: 204800,
              last_modified: new Date(Date.now() - 86400000).toISOString(),
              type: 'image/png',
              object_name: `${user.username}/test-image-2.png`
            }
          ]);
          setDebugInfo(prev => prev + '⚠️ Использую тестовые данные\n');
        } finally {
          setLoading(false);
          setDebugInfo(prev => prev + '✅ Загрузка завершена\n');
        }
      }
    };

    loadUserData();
  }, [user]);

  const loadFilesFromMinIO = async () => {
    setDebugInfo('🔄 Загружаю файлы из MinIO...\n');

    try {
      console.log('📁 [Profile] Запрашиваю файлы из MinIO...');

      // Метод 1: Пробуем через /minio-files endpoint
      try {
        const response = await fetch(`${apiService.baseUrl}/minio-files`, {
          headers: apiService.getHeaders(),
        });

        if (response.ok) {
          const data = await response.json();
          console.log('✅ [Profile] Got MinIO files:', data);

          if (data.files && data.files.length > 0) {
            const files = data.files.map((file: any) => ({
              name: file.filename || file.object_name?.split('/').pop() || 'unnamed',
              url: file.url,
              size: file.size || 0,
              last_modified: file.last_modified || new Date().toISOString(),
              type: file.content_type || 'image/jpeg',
              object_name: file.object_name
            }));

            setUserFiles(files);
            setDebugInfo(prev => prev + `✅ Загружено ${files.length} файлов из MinIO\n`);
            return;
          }
        }
      } catch (minioError) {
        console.log('⚠️ [Profile] /minio-files endpoint failed:', minioError);
      }

      // Метод 2: Пробуем через /files endpoint
      try {
        let files = await apiService.getUserFiles();
        console.log('📁 [Profile] Main method files:', files.length);

        if (files.length > 0) {
          setUserFiles(files);
          setDebugInfo(prev => prev + `✅ Загружено ${files.length} файлов через /files endpoint\n`);
          return;
        }
      } catch (filesError) {
        console.log('⚠️ [Profile] /files endpoint failed:', filesError);
      }

      // Метод 3: Пробуем альтернативный метод
      try {
        let files = await apiService.getUserFilesAlternative();
        console.log('📁 [Profile] Alternative method files:', files.length);

        if (files.length > 0) {
          setUserFiles(files);
          setDebugInfo(prev => prev + `✅ Загружено ${files.length} файлов через альтернативный метод\n`);
          return;
        }
      } catch (altError) {
        console.log('⚠️ [Profile] Alternative method failed:', altError);
      }

      // Если ничего не получилось
      setDebugInfo(prev => prev + '⚠️ Не удалось загрузить файлы из MinIO\n');

    } catch (error: any) {
      console.error('❌ [Profile] Error loading files from MinIO:', error);
      setDebugInfo(prev => prev + `❌ Ошибка загрузки файлов: ${error.message}\n`);
    }
  };

  const handleRefreshFiles = async () => {
    setRefreshing(true);
    setDebugInfo('🔄 Принудительная перезагрузка файлов...\n');

    try {
      await loadFilesFromMinIO();
      setDebugInfo(prev => prev + `✅ Файлы обновлены\n`);
    } catch (error: any) {
      console.error('❌ Error refreshing files:', error);
      setDebugInfo(prev => prev + `❌ Ошибка: ${error.message || error}\n`);
    } finally {
      setRefreshing(false);
    }
  };

  const runDebugTests = async () => {
    setDebugInfo('🧪 Запуск отладки endpoint\'ов...\n');
    await apiService.debugEndpoints();
    setDebugInfo(prev => prev + '✅ Отладка завершена (см. консоль браузера)\n');
  };

  const testFilesEndpoint = async () => {
    setDebugInfo('🧪 Тестирую endpoint /files...\n');
    await apiService.testFilesEndpoint();
    setDebugInfo(prev => prev + '✅ Тест завершен (см. консоль)\n');
  };

  const handleReauth = () => {
    // Очищаем токен и перенаправляем на логин
    apiService.clearToken();
    logout();
    window.location.href = '/login';
  };

  const checkMinioFiles = async () => {
    setDebugInfo('🔍 Проверка MinIO файлов...\n');
    try {
      const response = await fetch(`${apiService.baseUrl}/minio-files`, {
        headers: apiService.getHeaders(),
      });

      if (!response.ok) {
        throw new Error(`HTTP ${response.status}: ${response.statusText}`);
      }

      const data = await response.json();
      console.log('MinIO files data:', data);

      setDebugInfo(prev => prev + `✅ MinIO: ${data.total_files} файлов\n`);

      if (data.files && data.files.length > 0) {
        // Обновляем список файлов в UI
        const fileInfos: any[] = data.files.map((file: any) => ({
          name: file.filename || file.object_name?.split('/').pop() || 'unnamed',
          url: file.url,
          size: file.size || 0,
          object_name: file.object_name,
          last_modified: file.last_modified || new Date().toISOString(),
          type: file.content_type || 'image/jpeg'
        }));

        setUserFiles(fileInfos);
        setDebugInfo(prev => prev + '✅ Файлы загружены из MinIO\n');
      } else {
        setDebugInfo(prev => prev + '⚠️ Файлов в MinIO не найдено\n');
      }
    } catch (error: any) {
      console.error('Error checking MinIO files:', error);
      setDebugInfo(prev => prev + `❌ Ошибка: ${error.message}\n`);
    }
  };

  const testMinioConnection = async () => {
    setDebugInfo('🧪 Проверка MinIO...\n');
    try {
      const response = await fetch(`${apiService.baseUrl}/debug/minio-list/${user?.username}`, {
        headers: apiService.getHeaders(),
      });

      if (!response.ok) {
        throw new Error(`HTTP ${response.status}: ${response.statusText}`);
      }

      const data = await response.json();
      console.log('MinIO debug data:', data);
      setDebugInfo(prev => prev + `✅ MinIO: ${data.total_objects} объектов\n`);

      if (data.objects && data.objects.length > 0) {
        setDebugInfo(prev => prev + '📁 Файлы в MinIO:\n' + 
          data.objects.map((obj: any) => `  - ${obj.object_name} (${obj.size || 0} bytes)`).join('\n') + '\n');
      }
    } catch (error: any) {
      setDebugInfo(prev => prev + `❌ Ошибка MinIO: ${error.message}\n`);
    }
  };

  const createTestFiles = async () => {
    setDebugInfo('🧪 Создание тестовых файлов...\n');
    try {
      const response = await fetch(`${apiService.baseUrl}/debug/create-test-files`, {
        method: 'POST',
        headers: apiService.getHeaders(),
      });

      if (!response.ok) {
        throw new Error(`HTTP ${response.status}: ${response.statusText}`);
      }

      const data = await response.json();
      console.log('Test files created:', data);
      setDebugInfo(prev => prev + `✅ ${data.message}\n`);

      // Обновляем список файлов
      setTimeout(() => handleRefreshFiles(), 1000);

    } catch (error: any) {
      console.error('Error creating test files:', error);
      setDebugInfo(prev => prev + `❌ Ошибка: ${error.message}\n`);
    }
  };

  const formatFileSize = (bytes: number): string => {
    if (bytes === 0) return '0 Bytes';
    const k = 1024;
    const sizes = ['Bytes', 'KB', 'MB', 'GB'];
    const i = Math.floor(Math.log(bytes) / Math.log(k));
    return parseFloat((bytes / Math.pow(k, i)).toFixed(2)) + ' ' + sizes[i];
  };

  const formatDate = (dateString: string): string => {
    try {
      const date = new Date(dateString);
      return date.toLocaleDateString('ru-RU', {
        year: 'numeric',
        month: 'long',
        day: 'numeric',
        hour: '2-digit',
        minute: '2-digit'
      });
    } catch {
      return dateString;
    }
  };

  const handleDownload = async (url: string, filename: string) => {
    try {
      await apiService.downloadFile(url, filename);
    } catch (error) {
      console.error('Error downloading file:', error);
      alert('Ошибка при скачивании файла');
    }
  };

  const testFileDownload = async (objectName: string) => {
    setDebugInfo(prev => prev + `🧪 Тестирую скачивание: ${objectName}\n`);
    await apiService.testFileDownload(objectName);
    setDebugInfo(prev => prev + '✅ Тест завершен (см. консоль)\n');
  };

  const openFileInNewTab = (url: string) => {
    window.open(url, '_blank');
  };

  const copyToClipboard = (text: string, label: string) => {
    navigator.clipboard.writeText(text)
      .then(() => alert(`${label} скопировано в буфер обмена`))
      .catch(err => console.error('Ошибка копирования:', err));
  };

  if (!user) {
    return (
      <div className="profile-container">
        <div className="profile-card">
          <h2>⚠️ Доступ запрещен</h2>
          <p>Для просмотра профиля необходимо <a href="/login">войти в систему</a></p>
        </div>
      </div>
    );
  }

  if (loading) {
    return (
      <div className="profile-container">
        <div className="loading-spinner">
          <div className="spinner"></div>
          <p>Загрузка профиля...</p>
        </div>
      </div>
    );
  }

  return (
    <div className="user-profile">
      <div className="profile-header">
        <h1>👤 Профиль пользователя</h1>
        <div className={`user-badge ${user.is_admin ? 'admin' : 'user'}`}>
          {user.is_admin ? '👑 Администратор' : '👤 Пользователь'}
        </div>
      </div>

      {/* Debug section */}
      <div className="debug-section">
        <details>
          <summary>🛠️ Информация для отладки</summary>
          <div className="debug-controls">
            <button onClick={handleReauth} className="debug-button" style={{ background: 'linear-gradient(135deg, #f56565, #e53e3e)' }}>
              🔐 Переаутентификация
            </button>
            <button onClick={runDebugTests} className="debug-button">
              🐛 Debug All Endpoints
            </button>
            <button onClick={testFilesEndpoint} className="debug-button">
              🧪 Test /files Endpoint
            </button>
            <button onClick={testMinioConnection} className="debug-button">
              🗄️ Проверить MinIO
            </button>
            <button onClick={checkMinioFiles} className="debug-button">
              🔍 Проверить MinIO файлы
            </button>
            <button onClick={createTestFiles} className="debug-button">
              📝 Создать тест файлы
            </button>
            <button onClick={handleRefreshFiles} className="debug-button" disabled={refreshing}>
              {refreshing ? '🔄 Обновление...' : '🔄 Перезагрузить файлы'}
            </button>
          </div>
          <pre className="debug-info">
            {debugInfo}
            {'---\n'}
            Пользователь: {user.username} {user.is_admin ? '(Admin)' : ''}
            {'\nФайлов в состоянии: '}{userFiles.length}
            {'\nMinIO информация: '}{minioInfo ? 'Загружена' : 'Не загружена'}
            {'\nОшибка MinIO: '}{minioInfo?.error || 'Нет'}
            {'\nПапка пользователя: '}{minioInfo?.user_folder || 'Неизвестно'}
            {'\nBucket: '}{minioInfo?.files_bucket || minioInfo?.bucket || 'Неизвестно'}
            {'\nТокен в localStorage: '}{localStorage.getItem('token') ? 'Присутствует' : 'Отсутствует'}
            {'\nAPI Base URL: '}{apiService.baseUrl}
          </pre>
        </details>
      </div>

      <div className="profile-tabs">
        <button 
          className={`tab-button ${activeTab === 'account' ? 'active' : ''}`}
          onClick={() => setActiveTab('account')}
        >
          📋 Информация аккаунта
        </button>
        <button 
          className={`tab-button ${activeTab === 'files' ? 'active' : ''}`}
          onClick={() => setActiveTab('files')}
        >
          📁 История файлов ({userFiles.length})
        </button>
      </div>

      {activeTab === 'account' ? (
        <div className="profile-grid">
          <div className="profile-card">
            <h2>📋 Информация аккаунта</h2>
            <div className="info-grid">
              <div className="info-item">
                <span className="info-label">Имя пользователя:</span>
                <span className="info-value">{user.username}</span>
              </div>

              {user.email && (
                <div className="info-item">
                  <span className="info-label">Email:</span>
                  <span className="info-value">{user.email}</span>
                </div>
              )}

              {user.created_at && (
                <div className="info-item">
                  <span className="info-label">Дата регистрации:</span>
                  <span className="info-value">{formatDate(user.created_at)}</span>
                </div>
              )}

              <div className="info-item">
                <span className="info-label">Статус:</span>
                <span className="status-badge active">Активен</span>
              </div>

              {minioInfo && (
                <>
                  <div className="info-item">
                    <span className="info-label">Хранилище:</span>
                    <span className="info-value storage-badge">{minioInfo.provider || 'MinIO'}</span>
                  </div>

                  {minioInfo.user_folder && !minioInfo.error ? (
                    <div className="info-item">
                      <span className="info-label">Папка в MinIO:</span>
                      <span className="info-value code" 
                           onClick={() => copyToClipboard(minioInfo.user_folder, 'Путь к папке')}
                           style={{cursor: 'pointer', textDecoration: 'underline dotted'}}
                           title="Кликните чтобы скопировать">
                        {minioInfo.user_folder}
                      </span>
                    </div>
                  ) : minioInfo.error ? (
                    <div className="info-item error">
                      <span className="info-label">Статус MinIO:</span>
                      <span className="info-value error-text" title={minioInfo.error}>
                        ⚠️ Ошибка аутентификации
                      </span>
                    </div>
                  ) : null}

                  {(minioInfo.files_bucket || minioInfo.bucket) && !minioInfo.error && (
                    <div className="info-item">
                      <span className="info-label">Бакет:</span>
                      <span className="info-value">{minioInfo.files_bucket || minioInfo.bucket}</span>
                    </div>
                  )}

                  {minioInfo.storage_used && !minioInfo.error && (
                    <div className="info-item">
                      <span className="info-label">Использовано:</span>
                      <span className="info-value">{minioInfo.storage_used}</span>
                    </div>
                  )}
                </>
              )}
            </div>
          </div>

          <div className="profile-card">
            <h2>⚙️ Системная информация</h2>
            <div className="info-grid">
              <div className="info-item">
                <span className="info-label">Система цензурирования:</span>
                <span className="info-value">AI Face Detection</span>
              </div>

              <div className="info-item">
                <span className="info-label">Методы цензурирования:</span>
                <span className="info-value">Размытие, Пикселизация, Черные полосы</span>
              </div>

              <div className="info-item">
                <span className="info-label">Поддерживаемые форматы:</span>
                <span className="info-value">JPG, PNG, GIF, BMP, WEBP</span>
              </div>

              <div className="info-item">
                <span className="info-label">Максимальный размер файла:</span>
                <span className="info-value">10 MB</span>
              </div>

              <div className="info-item">
                <span className="info-label">MinIO Endpoint:</span>
                <span className="info-value">localhost:9000</span>
              </div>
            </div>
          </div>
        </div>
      ) : (
        <div className="files-section">
          <div className="files-header">
            <div className="header-title">
              <h2>📁 История файлов</h2>
              <span className="files-count">{userFiles.length} файлов</span>
            </div>
            <div className="header-actions">
              <button 
                onClick={handleRefreshFiles}
                className="refresh-button"
                disabled={refreshing}
              >
                {refreshing ? '🔄 Обновление...' : '🔄 Обновить файлы'}
              </button>
              <button 
                onClick={createTestFiles}
                className="refresh-button"
                style={{background: 'linear-gradient(135deg, #ed8936, #dd6b20)'}}
              >
                📝 Создать тест
              </button>
            </div>
          </div>

          {userFiles.length === 0 ? (
            <div className="empty-files">
              <div className="empty-icon">📭</div>
              <h3>Файлы не найдены</h3>
              <p>У вас пока нет загруженных файлов в системе</p>
              <p className="debug-hint">
                <small>
                  ⚠️ Если вы загружали файлы через редактор, но они здесь не отображаются, 
                  возможно проблема с доступом к MinIO или endpoint'ами.
                  <br />
                  Используйте кнопки отладки выше для диагностики.
                </small>
              </p>
              <div className="empty-actions">
                <a href="/redaction" className="upload-link">
                  🖼️ Перейти в редактор
                </a>
                <button 
                  onClick={createTestFiles}
                  className="demo-button"
                >
                  📝 Создать тест файлы
                </button>
                <button 
                  onClick={() => {
                    const demoFiles = [
                      {
                        name: 'demo-image-1.jpg',
                        url: 'https://via.placeholder.com/400x300/667eea/ffffff?text=Demo+1',
                        size: 153600,
                        last_modified: new Date().toISOString(),
                        type: 'image/jpeg',
                        object_name: 'admin/demo-image-1.jpg'
                      },
                      {
                        name: 'demo-image-2.jpg',
                        url: 'https://via.placeholder.com/400x300/764ba2/ffffff?text=Demo+2',
                        size: 204800,
                        last_modified: new Date(Date.now() - 3600000).toISOString(),
                        type: 'image/jpeg',
                        object_name: 'admin/demo-image-2.jpg'
                      }
                    ];
                    setUserFiles(demoFiles);
                  }}
                  className="demo-button"
                  style={{background: 'linear-gradient(135deg, #9f7aea, #805ad5)'}}
                >
                  🧪 Показать демо
                </button>
              </div>
            </div>
          ) : (
            <>
              {userFiles.some(file => file.url && file.url.includes('placeholder.com')) && (
                <div className="demo-warning">
                  ⚠️ Отображаются демо-данные. Реальные файлы из MinIO не загружены.
                  Проверьте консоль браузера для отладки.
                </div>
              )}

              <div className="files-grid">
                {userFiles.map((file, index) => (
                  <div key={index} className="file-card">
                    <div className="file-preview">
                      {file.url && (
                        file.url.match(/\.(jpg|jpeg|png|gif|bmp|webp)$/i) || 
                        file.type?.includes('image') || 
                        file.name?.match(/\.(jpg|jpeg|png|gif|bmp|webp)$/i)
                      ) ? (
                        <img 
                          src={file.url} 
                          alt={file.name} 
                          className="file-image"
                          onError={(e) => {
                            (e.target as HTMLImageElement).style.display = 'none';
                            const parent = e.currentTarget.parentElement;
                            if (parent) {
                              const fallback = document.createElement('div');
                              fallback.className = 'file-icon';
                              fallback.textContent = '📄';
                              parent.appendChild(fallback);
                            }
                          }}
                          loading="lazy"
                          onClick={() => openFileInNewTab(file.url)}
                          style={{ cursor: 'pointer' }}
                        />
                      ) : (
                        <div className="file-icon">
                          {file.name?.match(/\.(pdf)$/i) ? '📄' : 
                           file.name?.match(/\.(doc|docx)$/i) ? '📝' : 
                           file.name?.match(/\.(xls|xlsx)$/i) ? '📊' : 
                           '📁'}
                        </div>
                      )}
                    </div>

                    <div className="file-info">
                      <div className="file-name" title={file.name}>
                        {file.name || 'Без названия'}
                      </div>

                      <div className="file-details">
                        {file.size !== undefined && (
                          <span className="file-size">📦 {formatFileSize(file.size)}</span>
                        )}

                        {file.last_modified && (
                          <span className="file-date">📅 {formatDate(file.last_modified)}</span>
                        )}

                        {file.type && (
                          <span className="file-type">🎯 {file.type.split('/').pop() || file.type}</span>
                        )}
                      </div>

                      {file.object_name && (
                        <div className="file-object" 
                             title="Object name в MinIO (кликните чтобы скопировать)"
                             onClick={() => copyToClipboard(file.object_name, 'Object name')}
                             style={{cursor: 'pointer', textDecoration: 'underline dotted'}}>
                          🏷️ {file.object_name.length > 30 ? 
                            file.object_name.substring(0, 30) + '...' : 
                            file.object_name}
                        </div>
                      )}

                      {file.url && (
                        <div className="file-object" 
                             title="URL файла (кликните чтобы скопировать)"
                             onClick={() => copyToClipboard(file.url, 'URL файла')}
                             style={{cursor: 'pointer', textDecoration: 'underline dotted', fontSize: '0.8rem', marginTop: '5px'}}>
                          🔗 {file.url.length > 40 ? 
                            file.url.substring(0, 40) + '...' : 
                            file.url}
                        </div>
                      )}
                    </div>

                    <div className="file-actions">
                      {file.url && (
                        <button
                          onClick={() => openFileInNewTab(file.url)}
                          className="action-button view"
                          title="Открыть в новой вкладке"
                        >
                          👁️
                        </button>
                      )}

                      {file.url && (
                        <button 
                          onClick={() => handleDownload(file.url, file.name)}
                          className="action-button download"
                          title="Скачать"
                        >
                          ⬇️
                        </button>
                      )}

                      {file.url && (
                        <button 
                          onClick={() => copyToClipboard(file.url, 'Ссылка на файл')}
                          className="action-button copy"
                          title="Копировать ссылку"
                        >
                          📋
                        </button>
                      )}

                      {file.object_name && (
                        <button 
                          onClick={() => {
                            copyToClipboard(file.object_name, 'Object name');
                          }}
                          className="action-button copy"
                          title="Копировать Object name"
                          style={{background: 'rgba(237, 137, 54, 0.1)', color: '#ed8936'}}
                        >
                          🏷️
                        </button>
                      )}
                    </div>
                  </div>
                ))}
              </div>
            </>
          )}

          {minioInfo && (
            <div className="storage-info">
              <h3>💾 Информация о хранилище</h3>
              <div className="storage-details">
                <div className="storage-item">
                  <span className="storage-label">Провайдер:</span>
                  <span className="storage-value">{minioInfo.provider || 'MinIO'}</span>
                </div>

                <div className="storage-item">
                  <span className="storage-label">Бакет:</span>
                  <span className="storage-value">{minioInfo.files_bucket || minioInfo.bucket || 'user-files'}</span>
                </div>

                <div className="storage-item">
                  <span className="storage-label">Папка пользователя:</span>
                  <span className="storage-value code">{minioInfo.user_folder || user?.username}</span>
                </div>

                <div className="storage-item">
                  <span className="storage-label">Всего файлов:</span>
                  <span className="storage-value">{userFiles.length}</span>
                </div>

                <div className="storage-item">
                  <span className="storage-label">Общий размер:</span>
                  <span className="storage-value">
                    {formatFileSize(userFiles.reduce((sum, file) => sum + (file.size || 0), 0))}
                  </span>
                </div>

                {minioInfo.storage_used && (
                  <div className="storage-item">
                    <span className="storage-label">Использовано (MinIO):</span>
                    <span className="storage-value">{minioInfo.storage_used}</span>
                  </div>
                )}
              </div>
            </div>
          )}
        </div>
      )}
    </div>
  );
};

export default UserProfile;
